ALTER TABLE owner_applications ADD COLUMN IF NOT EXISTS pending_password_hash text, ADD COLUMN IF NOT EXISTS email_verified_at timestamptz, ADD COLUMN IF NOT EXISTS property_name text, ADD COLUMN IF NOT EXISTS property_location text, ADD COLUMN IF NOT EXISTS unit_count integer, ADD COLUMN IF NOT EXISTS decided_at timestamptz;
CREATE TABLE IF NOT EXISTS owner_signup_tokens(digest text PRIMARY KEY,email text NOT NULL,full_name text NOT NULL,phone text NOT NULL,property_name text NOT NULL,property_location text NOT NULL,unit_count integer NOT NULL,expires_at timestamptz NOT NULL);
